/**
 * Adhyarvansh — Cloudflare Worker
 * Private app — no self-registration
 * Users are pre-created via D1 console
 * Bindings: DB (D1), MF_CACHE (KV), JWT_SECRET (secret)
 */

const CORS = {
  'Access-Control-Allow-Origin':  '*',
  'Access-Control-Allow-Methods': 'GET, POST, PUT, DELETE, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type, Authorization',
}

export default {
  async fetch(request, env) {
    if (request.method === 'OPTIONS') {
      return new Response(null, { status: 204, headers: CORS })
    }

    const url    = new URL(request.url)
    const path   = url.pathname
    const method = request.method

    try {
      if (path === '/' || path === '')   return serveHTML()
      if (path === '/health')            return ok({ status: 'ok', db: 'D1' })
      if (path === '/test-db')           return testDB(env)
      if (path.startsWith('/auth'))      return authRouter(request, env, path, method)
      if (path.startsWith('/portfolio')) return portfolioRouter(request, env, path, method)
      if (path.startsWith('/watchlist')) return watchlistRouter(request, env, path, method)
      if (path.startsWith('/funds'))     return fundsRouter(request, env, path, method)
      if (path.startsWith('/logo/'))      return logoRoute(env, path)
      if (path === '/brand/email-logo.png') return emailLogo()
      if (path === '/brand/logo-white.png') return pngResponse(LOGO_WHITE_B64)
      if (path.startsWith('/profile'))    return profileRouter(request, env, path, method)
      if (path.startsWith('/nav/'))       return navProxy(env, path)
      if (path.startsWith('/digest'))     return digestRouter(env, path)
      if (path.startsWith('/admin'))      return adminRouter(request, env, path, method)
      return err('Not found', 404)
    } catch (e) {
      console.error('ERR:', e.message)
      return err(e.message || 'Server error', e.status ?? 500)
    }
  }
}

const _TEST_HTML = "";
// ── HTML — base64 embedded, zero cache/escaping issues ───────────────────────
const _HTML = "";

async function serveHTML() {
  const bin   = atob(_HTML)
  const bytes = new Uint8Array(bin.length)
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i)
  const html  = new TextDecoder().decode(bytes)
  return new Response(html, {
    headers: { 'Content-Type': 'text/html;charset=UTF-8', 'Cache-Control': 'no-store' }
  })
}

async function serveTestLogin() {
  const bin   = atob(_TEST_HTML)
  const bytes = new Uint8Array(bin.length)
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i)
  const html  = new TextDecoder().decode(bytes)
  return new Response(html, {
    headers: { 'Content-Type': 'text/html;charset=UTF-8', 'Cache-Control': 'no-store' }
  })
}

// ── D1 ────────────────────────────────────────────────────────────────────────
async function sql(env, query, params = []) {
  const stmt   = env.DB.prepare(query)
  const bound  = params.length > 0 ? stmt.bind(...params) : stmt
  const result = await bound.all()
  return result.results || []
}

async function sqlRun(env, query, params = []) {
  const stmt  = env.DB.prepare(query)
  const bound = params.length > 0 ? stmt.bind(...params) : stmt
  return await bound.run()
}

async function testDB(env) {
  try {
    const rows = await sql(env, "SELECT datetime('now') as t")
    return ok({ db: 'D1 ok', time: rows[0]?.t })
  } catch(e) {
    return err('DB: ' + e.message, 500)
  }
}

// ═══════════════════════════════════════════════════════════
// AUTH — login only (no self-registration — private app)
// ═══════════════════════════════════════════════════════════

async function authRouter(request, env, path, method) {
  if (path === '/auth/login' && method === 'POST') return login(request, env)
  if (path === '/auth/me'    && method === 'GET')  return me(request, env)
  // Registration disabled — users pre-created via D1 console
  if (path === '/auth/register') return err('Registration is closed. Contact the admin.', 403)
  return err('Not found', 404)
}

async function login(request, env) {
  let body
  try { body = await request.json() } catch { return err('Invalid JSON', 400) }

  const { email, password } = body
  if (!email || !password) return err('Email and password required', 400)

  const rows = await sql(env,
    'SELECT id, name, email, password_hash, is_active FROM users WHERE email = ?',
    [email.toLowerCase().trim()])

  const user = rows[0]

  // Always run hash check even on miss (prevents timing attacks)
  const match = user ? await checkPwd(password, user.password_hash) : false

  if (!user || !match) return err('Invalid email or password', 401)
  if (!user.is_active)  return err('Account deactivated', 403)

  const token = await makeJWT(user.id, user.email, env.JWT_SECRET)
  return ok({ token, user_id: user.id, name: user.name, email: user.email })
}

async function me(request, env) {
  const payload = await verifyJWT(request, env)
  const rows    = await sql(env,
    'SELECT id, name, email FROM users WHERE id = ?', [payload.sub])
  if (!rows.length) return err('User not found', 404)
  return ok(rows[0])
}

// ═══════════════════════════════════════════════════════════
// PORTFOLIO
// ═══════════════════════════════════════════════════════════

// Portfolio & journal now live in SUPABASE (RLS-scoped per user via the user's
// own JWT). Fund NAV + AI signals stay in D1 (mf_cache, ai_recommendations) and
// are merged in JS, since a SQL JOIN can't span the two databases.

function getUserToken(request) {
  return (request.headers.get('Authorization') || '').replace('Bearer ', '').trim()
}

// Look up NAV + AI data from D1 for a set of scheme_codes. Returns a map keyed by scheme_code.
async function fundDataMap(env, schemeCodes) {
  const codes = [...new Set(schemeCodes.filter(Boolean).map(String))]
  if (!codes.length) return {}
  const placeholders = codes.map(() => '?').join(',')
  const rows = await sql(env, `
    SELECT m.scheme_code, m.latest_nav, m.sub_category, m.return_1y, m.return_3y, m.return_5y,
           ai.signal, ai.risk_score, ai.risk_label, ai.rationale,
           ai.composite_score, ai.signal_reason, ai.strength, ai.weakness
    FROM mf_cache m
    LEFT JOIN ai_recommendations ai ON ai.scheme_code = m.scheme_code
    WHERE m.scheme_code IN (${placeholders})`, codes)
  const map = {}
  for (const r of rows) map[String(r.scheme_code)] = r
  return map
}

async function portfolioRouter(request, env, path, method) {
  let payload
  try { payload = await verifyJWT(request, env) }
  catch(e) { return err(e.message, 401) }

  const uid       = payload.sub
  const userToken = getUserToken(request)
  const exitMatch = path.match(/^\/portfolio\/(\d+)\/exit$/)

  try {
    if (exitMatch                     && method === 'POST') return await recordExit(request, env, userToken, uid, +exitMatch[1])
    if (path === '/portfolio/summary' && method === 'GET')  return await getSummary(env, userToken)
    if (path === '/portfolio/all'     && method === 'GET')  return await listAllInvestments(env, userToken)
    if (path === '/portfolio/exits'   && method === 'GET')  return await listExits(env, userToken)
    if (path === '/portfolio'         && method === 'GET')  return await listHoldings(env, userToken)
    if (path === '/portfolio'         && method === 'POST') return await addInvestment(request, env, userToken, uid)
    return err('Not found', 404)
  } catch (e) {
    return err(e.message || 'Portfolio error', e.status || 500)
  }
}


// ── Watchlist (per user, Supabase, RLS-isolated) ─────────────────────────────
async function watchlistRouter(request, env, path, method) {
  let payload
  try { payload = await verifyJWT(request, env) }
  catch(e) { return err(e.message, 401) }
  const uid = payload.sub
  const userToken = getUserToken(request)
  const one = path.match(/^\/watchlist\/([^/]+)$/)
  try {
    if (path === '/watchlist' && method === 'GET') {
      const rows = await sbRest(userToken, 'watchlist?select=*&order=added_at.desc')
      const fmap = await fundDataMap(env, rows.map(r => r.scheme_code))
      return ok(rows.map(r => {
        const m = fmap[String(r.scheme_code)] || {}
        return { ...r,
          fund_name: m.fund_name || r.fund_name, amc_name: m.amc_name || r.amc_name,
          category: m.category || r.category,
          signal: m.signal ?? null, return_1y: m.return_1y ?? null,
          return_3y: m.return_3y ?? null, return_5y: m.return_5y ?? null,
          latest_nav: m.latest_nav ?? null }
      }))
    }
    if (path === '/watchlist' && method === 'POST') {
      const body = await request.json()
      const items = (Array.isArray(body.items) ? body.items : [body]).filter(i => i && i.scheme_code)
      if (!items.length) return err('scheme_code required', 400)
      const rows = items.slice(0, 200).map(i => ({
        user_id: uid, scheme_code: String(i.scheme_code),
        fund_name: i.fund_name || null, amc_name: i.amc_name || null, category: i.category || null,
        ...(i.added_at ? { added_at: i.added_at } : {})
      }))
      await sbRest(userToken, 'watchlist?on_conflict=user_id,scheme_code', {
        method: 'POST', body: rows, prefer: 'resolution=merge-duplicates,return=minimal' })
      return ok({ saved: rows.length }, 201)
    }
    if (one && method === 'DELETE') {
      await sbRest(userToken, 'watchlist?scheme_code=eq.' + encodeURIComponent(decodeURIComponent(one[1])), { method: 'DELETE' })
      return ok({ removed: true })
    }
    if (path === '/watchlist' && method === 'DELETE') {
      await sbRest(userToken, 'watchlist?scheme_code=not.is.null', { method: 'DELETE' })
      return ok({ cleared: true })
    }
    return err('Not found', 404)
  } catch (e) {
    return err(e.message || 'Watchlist error', e.status || 500)
  }
}

async function listAllInvestments(env, userToken) {
  const rows = await sbRest(userToken,
    'portfolio_entries?select=*&order=purchase_date.desc')
  const fmap = await fundDataMap(env, rows.map(r => r.scheme_code))
  const out = rows.map(p => {
    const m = fmap[String(p.scheme_code)] || {}
    return { ...p,
      latest_nav: m.latest_nav ?? null, sub_category: m.sub_category ?? null,
      return_1y: m.return_1y ?? null, return_3y: m.return_3y ?? null, return_5y: m.return_5y ?? null,
      signal: m.signal ?? null, risk_label: m.risk_label ?? null, risk_score: m.risk_score ?? null }
  })
  return ok(out)
}

async function listExits(env, userToken) {
  const rows = await sbRest(userToken,
    'journal_exits?select=*&order=exit_date.desc')
  return ok(rows)
}

async function listHoldings(env, userToken) {
  const rows = await sbRest(userToken,
    'portfolio_entries?select=*&is_active=eq.true&order=purchase_date.desc')
  const fmap = await fundDataMap(env, rows.map(r => r.scheme_code))
  const out = rows.map(p => {
    const m   = fmap[String(p.scheme_code)] || {}
    const nav = (m.latest_nav != null) ? m.latest_nav : p.purchase_nav
    const cur = Math.round(nav * p.units * 100) / 100
    return { ...p,
      latest_nav: m.latest_nav ?? null,
      current_value: cur,
      gain_loss: Math.round((cur - p.invested_amount) * 100) / 100,
      signal: m.signal ?? null, risk_score: m.risk_score ?? null,
      risk_label: m.risk_label ?? null, rationale: m.rationale ?? null,
      composite_score: m.composite_score ?? null, signal_reason: m.signal_reason ?? null,
      strength: m.strength ?? null, weakness: m.weakness ?? null,
      return_1y: m.return_1y ?? null, return_3y: m.return_3y ?? null }
  })
  return ok(out)
}

async function addInvestment(request, env, userToken, uid) {
  let b
  try { b = await request.json() } catch { return err('Invalid JSON', 400) }
  const { scheme_code, fund_name, category, amc_name, units, purchase_nav, purchase_date, notes } = b
  if (!fund_name || !units || !purchase_nav || !purchase_date)
    return err('fund_name, units, purchase_nav, purchase_date required', 400)

  const sc = (scheme_code || '').trim() || null
  const invested = Math.round(parseFloat(units) * parseFloat(purchase_nav) * 100) / 100
  // RLS requires user_id = auth.uid(); include it explicitly.
  const row = {
    user_id: uid,                       // required by RLS: auth.uid() = user_id
    scheme_code: sc, fund_name, category: category || null, amc_name: amc_name || null,
    units: parseFloat(units), purchase_nav: parseFloat(purchase_nav),
    purchase_date, invested_amount: invested, is_active: true, notes: notes || null
  }
  const created = await sbRest(userToken, 'portfolio_entries', {
    method: 'POST', body: row, prefer: 'return=representation'
  })
  return ok(Array.isArray(created) ? created[0] : created, 201)
}

async function recordExit(request, env, userToken, uid, entryId) {
  let b
  try { b = await request.json() } catch { return err('Invalid JSON', 400) }
  const { units_sold, exit_nav, exit_date, notes } = b
  if (!units_sold || !exit_nav || !exit_date) return err('units_sold, exit_nav, exit_date required', 400)

  const entries = await sbRest(userToken,
    `portfolio_entries?select=*&id=eq.${entryId}&is_active=eq.true`)
  if (!entries.length) return err('Entry not found', 404)
  const e = entries[0]

  const exitAmt = parseFloat(units_sold) * parseFloat(exit_nav)
  const gain    = Math.round((exitAmt - (parseFloat(units_sold)/parseFloat(e.units))*parseFloat(e.invested_amount))*100)/100
  const days    = Math.floor((new Date(exit_date) - new Date(e.purchase_date)) / 86400000)
  const tax     = days >= 365 ? 'LTCG' : 'STCG'

  await sbRest(userToken, 'journal_exits', {
    method: 'POST',
    body: {
      user_id: uid,                       // required by RLS: auth.uid() = user_id
      portfolio_entry_id: entryId, scheme_code: e.scheme_code, fund_name: e.fund_name,
      units_sold: parseFloat(units_sold), exit_nav: parseFloat(exit_nav), exit_date,
      exit_amount: exitAmt, realised_gain: gain, holding_days: days, tax_type: tax, notes: notes || null
    }
  })

  if (parseFloat(units_sold) >= parseFloat(e.units)) {
    await sbRest(userToken, `portfolio_entries?id=eq.${entryId}`, {
      method: 'PATCH', body: { is_active: false }
    })
  } else {
    const rem = parseFloat(e.units) - parseFloat(units_sold)
    await sbRest(userToken, `portfolio_entries?id=eq.${entryId}`, {
      method: 'PATCH',
      body: { units: rem, invested_amount: (rem/parseFloat(e.units))*parseFloat(e.invested_amount) }
    })
  }
  return ok({ success: true, realised_gain: gain, holding_days: days, tax_type: tax })
}

async function getSummary(env, userToken) {
  const rows = await sbRest(userToken,
    'portfolio_entries?select=scheme_code,units,invested_amount&is_active=eq.true')
  if (!rows.length) return ok({ total_funds: 0, total_invested: 0, current_value: 0, total_gain: 0 })
  const fmap = await fundDataMap(env, rows.map(r => r.scheme_code))
  let invested = 0, current = 0
  for (const p of rows) {
    const m   = fmap[String(p.scheme_code)] || {}
    const nav = (m.latest_nav != null) ? m.latest_nav : p.purchase_nav
    invested += p.invested_amount
    current  += nav * p.units
  }
  return ok({
    total_funds: rows.length,
    total_invested: Math.round(invested * 100) / 100,
    current_value:  Math.round(current * 100) / 100,
    total_gain:     Math.round((current - invested) * 100) / 100
  })
}

