async function fundsRouter(request, env, path, method) {
  if (method !== 'GET') return err('Method not allowed', 405)
  const url = new URL(request.url)
  if (path === '/funds/top')    return topFunds(env, url)
  if (path === '/funds/picks')  return picksRoute(request, env)
  if (path === '/funds/search') return searchFunds(env, url)
  if (path === '/funds')        return listFunds(env, url)
  const code = path.replace('/funds/', '').trim()
  if (code) return fundDetail(env, code)
  return err('Not found', 404)
}


// ── Rule-based picks from a user's fund preferences ──────────────────────────
const GOAL_TXT = { wealth: 'long-term wealth', income: 'regular income', tax: 'tax saving', parking: 'parking cash', goal: 'a specific goal' }
async function picksRoute(request, env) {
  let payload
  try { payload = await verifyJWT(request, env) } catch (e) { return err(e.message, 401) }
  const rows = await sbRest(getUserToken(request), 'user_prefs?select=fund_prefs&limit=1')
  const fp = rows && rows[0] && rows[0].fund_prefs
  if (!fp || fp.skipped || !fp.risk) return ok({ picks: [], needs_prefs: true })

  const goals = Array.isArray(fp.goals) ? fp.goals : []
  const hz = fp.horizon || '3-5'
  let risk = Math.min(5, Math.max(1, parseInt(fp.risk) || 3))
  // horizon caps risk: short horizons cannot carry high-risk funds
  const hzCap = { '<1': 2, '1-3': 3, '3-5': 4, '5-10': 5, '10+': 5 }[hz] || 4
  risk = Math.min(risk, hzCap)

  let cats = Array.isArray(fp.categories) && fp.categories.length ? fp.categories.slice() : []
  if (!cats.length) {
    if (hz === '<1') cats = ['Debt']
    else if (hz === '1-3') cats = ['Debt', 'Hybrid']
    else cats = ['Equity', 'Hybrid', 'Debt']
  }
  if (goals.includes('income') && !fp.categories) cats = ['Debt', 'Hybrid']
  const conds = ["(m.nav_date IS NULL OR substr(m.nav_date,7,4) >= '2024')", "ai.signal IN ('strong_buy','buy')", 'ai.risk_score <= ?']
  const p = [risk]
  conds.push('m.category IN (' + cats.map(() => '?').join(',') + ')'); p.push(...cats)
  if (fp.direct !== false) conds.push("m.fund_name LIKE '%Direct%'")
  conds.push("m.fund_name NOT LIKE '%IDCW%' AND m.fund_name NOT LIKE '%Dividend%'")
  if (goals.includes('tax') && goals.length === 1) conds.push("(m.fund_name LIKE '%ELSS%' OR m.fund_name LIKE '%Tax Saver%' OR m.fund_name LIKE '%Tax Advantage%')")
  const orderCol = (hz === '<1' || hz === '1-3') ? 'm.return_1y' : 'm.return_3y'
  const out = await sql(env,
    'SELECT m.scheme_code,m.fund_name,m.category,m.sub_category,m.amc_name,m.latest_nav,m.nav_date,m.return_1y,m.return_3y,m.return_5y,' +
    'ai.signal,ai.risk_score,ai.risk_label FROM mf_cache m JOIN ai_recommendations ai ON ai.scheme_code=m.scheme_code WHERE ' +
    conds.join(' AND ') + ' AND ' + orderCol + ' IS NOT NULL ORDER BY ' + orderCol + ' DESC LIMIT 5', p)
  const goalTxt = goals.map(g => GOAL_TXT[g]).filter(Boolean).join(' & ') || 'your goals'
  const picks = out.map(f => ({ ...f, why: (f.signal === 'strong_buy' ? 'Strong Buy' : 'Buy') + ' · ' + (f.risk_label || ('Risk ' + f.risk_score)) + ' risk · fits ' + goalTxt + ' over ' + hz.replace('<1', 'under 1') + ' yrs' }))
  return ok({ picks, needs_prefs: false })
}

async function listFunds(env, url) {
  const cat     = url.searchParams.get('category')     || ''
  const sub     = url.searchParams.get('sub_category') || ''
  const sig     = url.searchParams.get('signal')       || ''
  const active  = url.searchParams.get('active') !== 'false'
  const rlbl    = url.searchParams.get('risk_label')   || ''
  const minRet  = url.searchParams.get('min_return')   || ''
  const q       = (url.searchParams.get('q') || '').trim()
  const srt     = url.searchParams.get('sort')         || 'return_1y'
  const page    = Math.max(1, parseInt(url.searchParams.get('page') || '1'))
  const limit   = 50
  const offset  = (page - 1) * limit

  const conds = []
  const p     = []

  if (active) conds.push("(m.nav_date IS NULL OR substr(m.nav_date,7,4) >= '2024')")
  if (cat)    { conds.push('m.category = ?');     p.push(cat) }
  if (sub)    { conds.push('m.sub_category = ?'); p.push(sub) }
  if (rlbl)   { conds.push('ai.risk_label = ?');  p.push(rlbl) }
  if (q)      { conds.push('(m.fund_name LIKE ? OR m.amc_name LIKE ?)'); p.push('%'+q+'%', '%'+q+'%') }
  if (sig)    { conds.push('ai.signal = ?');      p.push(sig) }
  if (minRet) { conds.push('m.return_1y >= ?');   p.push(parseFloat(minRet)) }

  const where   = conds.length ? 'WHERE ' + conds.join(' AND ') : ''
  const sortCol = ['return_1y','return_3y','return_5y','latest_nav'].includes(srt) ? 'm.' + srt : 'm.return_1y'

  const cr    = await sql(env, 'SELECT COUNT(*) as n FROM mf_cache m LEFT JOIN ai_recommendations ai ON ai.scheme_code = m.scheme_code ' + where, p)
  const total = parseInt(cr[0]?.n || 0)
  const pages = Math.max(1, Math.ceil(total / limit))

  const rows = await sql(env,
    'SELECT m.scheme_code, m.fund_name, m.category, m.sub_category, m.amc_name,' +
    ' m.latest_nav, m.nav_date, m.return_1y, m.return_3y, m.return_5y,' +
    ' ai.signal, ai.risk_score, ai.risk_label,' +
    ' ai.expected_1y_min, ai.expected_1y_max,' +
    ' ai.expected_3y_min, ai.expected_3y_max,' +
    ' ai.expected_5y_min, ai.expected_5y_max,' +
    ' ai.rationale' +
    ' FROM mf_cache m' +
    ' LEFT JOIN ai_recommendations ai ON ai.scheme_code = m.scheme_code' +
    ' ' + where +
    ' ORDER BY ' + sortCol + ' DESC' +
    ' LIMIT ? OFFSET ?',
    [...p, limit, offset])

  return ok({ funds: rows, page, limit, total, pages })
}

// ═══════════════════════════════════════════════════════════
// ADMIN — cache purge (called by the daily GitHub Action)
// Auth: Authorization: Bearer <JWT_SECRET>. No user JWT involved.
// Bumps cacheVer so all fund:/top: caches are orphaned at once.
// ═══════════════════════════════════════════════════════════
async function adminRouter(request, env, path, method) {
  // Constant-ish-time bearer check against the JWT_SECRET
  const auth = request.headers.get('Authorization') || ''
  const token = auth.startsWith('Bearer ') ? auth.slice(7) : ''
  const secret = env.JWT_SECRET || ''
  if (!secret || token.length !== secret.length || token !== secret) {
    return err('Unauthorized', 401)
  }
  if (path === '/admin/purge' && method === 'POST') {
    let cur = 1
    try { cur = parseInt(await env.MF_CACHE.get('cacheVer')) || 1 } catch (e) {}
    const next = String(cur + 1)
    await env.MF_CACHE.put('cacheVer', next)
    return ok({ purged: true, cacheVer: next })
  }
  return err('Not found', 404)
}

async function digestRouter(env, path) {
  // /digest/latest  -> most recent digest
  // /digest/list    -> last 30 digests (archive)
  try {
    if (path === '/digest/latest') return getLatestDigest(env)
    if (path === '/digest/list')   return listDigests(env)
    return err('Not found', 404)
  } catch (e) {
    // Table may not exist yet (before first GitHub Action run) — fail soft
    return ok({ digest: null, note: 'no digest available' })
  }
}

async function getLatestDigest(env) {
  try {
    const rows = await sql(env,
      'SELECT digest_date, headline, summary, items, sentiment, generated_at' +
      ' FROM market_digest ORDER BY digest_date DESC LIMIT 1')
    if (!rows.length) return ok({ digest: null })
    const d = rows[0]
    return ok({ digest: {
      date: d.digest_date,
      headline: d.headline,
      summary: d.summary,
      items: safeParse(d.items),
      sentiment: d.sentiment,
      generated_at: d.generated_at
    }})
  } catch (e) {
    return ok({ digest: null, note: 'table not ready' })
  }
}

async function listDigests(env) {
  try {
    const rows = await sql(env,
      'SELECT digest_date, headline, summary, items, sentiment, generated_at' +
      ' FROM market_digest ORDER BY digest_date DESC LIMIT 30')
    return ok({ digests: rows.map(function(d){ return {
      date: d.digest_date, headline: d.headline, summary: d.summary,
      items: safeParse(d.items), sentiment: d.sentiment, generated_at: d.generated_at
    }}) })
  } catch (e) {
    return ok({ digests: [] })
  }
}

function safeParse(s) {
  try { return JSON.parse(s || '[]') } catch(e) { return [] }
}

async function navProxy(env, path) {
  const code = path.replace('/nav/', '').trim()
  if (!code || !/^\d+$/.test(code)) return err('Invalid scheme code', 400)
  // KV cache (6h) to avoid hammering mfapi + speed up repeat loads
  const cacheKey = `nav:${code}`
  try {
    const cached = await env.MF_CACHE.get(cacheKey)
    if (cached) return new Response(cached, { status: 200, headers: { 'Content-Type':'application/json', ...CORS } })
  } catch(e) {}
  try {
    const r = await fetch('https://api.mfapi.in/mf/' + code, { cf: { cacheTtl: 21600 } })
    if (!r.ok) return err('NAV source error: ' + r.status, 502)
    const text = await r.text()
    // sanity check it's JSON with data
    let parsed
    try { parsed = JSON.parse(text) } catch(pe) { return err('NAV parse error', 502) }
    if (!parsed || !parsed.data || !parsed.data.length) {
      return ok({ data: [], meta: parsed && parsed.meta, note: 'no nav history for this scheme code' })
    }
    try { await env.MF_CACHE.put(cacheKey, text, { expirationTtl: 21600 }) } catch(e) {}
    return new Response(text, { status: 200, headers: { 'Content-Type':'application/json', ...CORS } })
  } catch(e) {
    return err('NAV fetch failed: ' + e.message, 502)
  }
}

// ═══════════════════════════════════════════════════════════
// CACHE VERSIONING
// All derived caches (fund detail, top funds) are prefixed with a
// version tag stored in KV. Bumping the version (via /admin/purge,
// called by the daily GitHub Action) instantly orphans every old
// cache entry so fresh AI data is served immediately after a sync.
// Old entries expire on their own TTL — no need to enumerate keys.
// ═══════════════════════════════════════════════════════════
async function cacheVer(env) {
  try {
    const v = await env.MF_CACHE.get('cacheVer')
    return v || '1'
  } catch (e) { return '1' }
}

async function fundDetail(env, code) {
  const ver = await cacheVer(env)
  const key = `fund:${ver}:${code}`
  const c = await env.MF_CACHE.get(key)
  if (c) return ok(JSON.parse(c))
  const rows = await sql(env, `
    SELECT m.*,ai.signal,ai.risk_score,ai.risk_label,ai.composite_score,
           ai.expected_1y_min,ai.expected_1y_max,ai.expected_3y_min,ai.expected_3y_max,
           ai.expected_5y_min,ai.expected_5y_max,
           ai.rationale,ai.strength,ai.weakness,ai.signal_reason,
           ai.sharpe_ratio,ai.sortino_ratio,ai.max_drawdown,
           ai.std_dev,ai.consistency_pct,ai.signal_layers
    FROM mf_cache m
    LEFT JOIN ai_recommendations ai ON ai.scheme_code=m.scheme_code
    WHERE m.scheme_code=?`, [code])
  if (!rows.length) return err('Fund not found', 404)
  await env.MF_CACHE.put(key, JSON.stringify(rows[0]), { expirationTtl: 21600 })
  return ok(rows[0])
}

async function searchFunds(env, url) {
  const q = (url.searchParams.get('q')||'').trim()
  if (q.length < 2) return ok({ funds: [] })
  const like = `%${q}%`
  const rows = await sql(env, `
    SELECT m.scheme_code,m.fund_name,m.category,m.amc_name,
           m.latest_nav,m.return_1y,m.return_3y,m.return_5y,
           ai.signal,ai.risk_score,ai.risk_label
    FROM mf_cache m
    LEFT JOIN ai_recommendations ai ON ai.scheme_code=m.scheme_code
    WHERE m.fund_name LIKE ? OR m.amc_name LIKE ?
    ORDER BY m.return_1y DESC LIMIT 20`, [like, like])
  return ok({ funds: rows })
}

async function topFunds(env, url) {
  const by  = url.searchParams.get('by')||'1y'
  const col = by==='3y'?'return_3y':by==='5y'?'return_5y':'return_1y'
  const ver = await cacheVer(env)
  const c   = await env.MF_CACHE.get(`top:${ver}:${by}`)
  if (c) return ok(JSON.parse(c))
  const rows = await sql(env, `
    SELECT m.scheme_code,m.fund_name,m.category,m.amc_name,
           m.latest_nav,m.return_1y,m.return_3y,m.return_5y,
           ai.signal,ai.risk_score,ai.risk_label
    FROM mf_cache m
    LEFT JOIN ai_recommendations ai ON ai.scheme_code=m.scheme_code
    WHERE m.${col} IS NOT NULL ORDER BY m.${col} DESC LIMIT 10`)
  await env.MF_CACHE.put(`top:${ver}:${by}`, JSON.stringify(rows), { expirationTtl: 21600 })
  return ok(rows)
}

// ═══════════════════════════════════════════════════════════
// PASSWORD — SHA-256 with fixed salt prefix (fast, <0.5ms)
// Format stored in DB: "salt:hash"
// ═══════════════════════════════════════════════════════════

async function checkPwd(password, stored) {
  try {
    const idx        = stored.indexOf(':')
    if (idx < 0) return false
    const salt       = stored.substring(0, idx)
    const storedHash = stored.substring(idx + 1)
    const input      = salt + ':' + password + ':' + salt
    const buf        = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(input))
    const hash       = toHex(new Uint8Array(buf))
    return hash === storedHash
  } catch(e) {
    console.error('checkPwd error:', e.message)
    return false
  }
}

// ═══════════════════════════════════════════════════════════
// JWT
// ═══════════════════════════════════════════════════════════

async function makeJWT(userId, email, secret) {
  const b = s => btoa(s).replace(/=/g,'').replace(/\+/g,'-').replace(/\//g,'_')
  const h = b(JSON.stringify({ alg:'HS256', typ:'JWT' }))
  const p = b(JSON.stringify({ sub:userId, email, exp: Math.floor(Date.now()/1000)+30*86400 }))
  const k = await crypto.subtle.importKey('raw', new TextEncoder().encode(secret),
    { name:'HMAC', hash:'SHA-256' }, false, ['sign'])
  const s = await crypto.subtle.sign('HMAC', k, new TextEncoder().encode(`${h}.${p}`))
  const sig = btoa(String.fromCharCode(...new Uint8Array(s))).replace(/=/g,'').replace(/\+/g,'-').replace(/\//g,'_')
  return `${h}.${p}.${sig}`
}

// Supabase project constants (public values).
const SUPABASE_URL = 'https://ybctubrwzostmaslrlxz.supabase.co'
const SUPABASE_PUBLISHABLE_KEY = 'sb_publishable_DLd-nA8Y06lI6L2I4V5P8w_3pLbx173'
const SUPABASE_JWKS_URL = SUPABASE_URL + '/auth/v1/.well-known/jwks.json'

// Supabase REST (PostgREST) call made AS THE USER (their JWT) so RLS scopes
// every row to them automatically. userToken is the raw Supabase access token.
async function sbRest(userToken, pathAndQuery, opts = {}) {
  const res = await fetch(SUPABASE_URL + '/rest/v1/' + pathAndQuery, {
    method: opts.method || 'GET',
    headers: {
      'apikey': SUPABASE_PUBLISHABLE_KEY,
      'Authorization': 'Bearer ' + userToken,
      'Content-Type': 'application/json',
      ...(opts.prefer ? { 'Prefer': opts.prefer } : {}),
      ...(opts.headers || {})
    },
    ...(opts.body ? { body: JSON.stringify(opts.body) } : {})
  })
  const text = await res.text()
  let data
  try { data = text ? JSON.parse(text) : null } catch { data = null }
  if (!res.ok) {
    throw Object.assign(new Error((data && data.message) || ('Supabase ' + res.status)), { status: res.status })
  }
  return data
}

function b64urlToBytes(s) {
  return Uint8Array.from(atob(s.replace(/-/g,'+').replace(/_/g,'/')), c => c.charCodeAt(0))
}
function decodeJwtPart(s) {
  return JSON.parse(new TextDecoder().decode(b64urlToBytes(s)))
}

async function getSupabaseJwks(env) {
  // Cache the JWKS in KV for 1h; keys rotate rarely.
  try {
    const cached = await env.MF_CACHE.get('supabase_jwks')
    if (cached) return JSON.parse(cached)
  } catch (e) {}
  const r = await fetch(SUPABASE_JWKS_URL)
  if (!r.ok) throw Object.assign(new Error('JWKS fetch failed'), { status: 401 })
  const jwks = await r.json()
  try { await env.MF_CACHE.put('supabase_jwks', JSON.stringify(jwks), { expirationTtl: 3600 }) } catch (e) {}
  return jwks
}

async function verifySupabaseJWT(token, env) {
  const [h, p, s] = token.split('.')
  const header = decodeJwtPart(h)
  const data   = decodeJwtPart(p)
  if (data.exp && data.exp < Date.now()/1000) throw Object.assign(new Error('Token expired'), { status:401 })

  const jwks = await getSupabaseJwks(env)
  const jwk  = (jwks.keys || []).find(k => k.kid === header.kid) || (jwks.keys || [])[0]
  if (!jwk) throw Object.assign(new Error('No matching key'), { status:401 })

  const key = await crypto.subtle.importKey(
    'jwk',
    { kty: jwk.kty, crv: jwk.crv, x: jwk.x, y: jwk.y, ext: true },
    { name: 'ECDSA', namedCurve: 'P-256' },
    false,
    ['verify']
  )
  const sig = b64urlToBytes(s)
  const ok2 = await crypto.subtle.verify(
    { name: 'ECDSA', hash: 'SHA-256' },
    key, sig, new TextEncoder().encode(`${h}.${p}`)
  )
  if (!ok2) throw Object.assign(new Error('Invalid token'), { status:401 })

  // Normalise to the shape the rest of the worker expects: .sub = user id,
  // plus .email and a .supabase flag for downstream handlers.
  return { sub: data.sub, email: data.email, supabase: true, name: (data.user_metadata && data.user_metadata.name) || '' }
}

async function verifyJWT(request, env) {
  const hdr   = request.headers.get('Authorization') || ''
  const token = hdr.replace('Bearer ','').trim()
  if (!token) throw Object.assign(new Error('No token'), { status:401 })
  const parts = token.split('.')
  if (parts.length !== 3) throw Object.assign(new Error('Bad token'), { status:401 })
  const [h, p, s] = parts

  // Route by signing algorithm in the JWT header.
  let header
  try { header = decodeJwtPart(h) } catch (e) { throw Object.assign(new Error('Bad token header'), { status:401 }) }

  if (header.alg === 'ES256') {
    // Supabase token
    return verifySupabaseJWT(token, env)
  }

  // Legacy HS256 token (old password login) — kept during transition.
  const data = JSON.parse(atob(p.replace(/-/g,'+').replace(/_/g,'/')))
  if (data.exp < Date.now()/1000) throw Object.assign(new Error('Token expired'), { status:401 })
  const k = await crypto.subtle.importKey('raw', new TextEncoder().encode(env.JWT_SECRET),
    { name:'HMAC', hash:'SHA-256' }, false, ['verify'])
  const sig = Uint8Array.from(atob(s.replace(/-/g,'+').replace(/_/g,'/')), c=>c.charCodeAt(0))
  const ok2 = await crypto.subtle.verify('HMAC', k, sig, new TextEncoder().encode(`${h}.${p}`))
  if (!ok2) throw Object.assign(new Error('Invalid token'), { status:401 })
  return data
}

