function escHtml(s) { return String(s || '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c])) }
function firstName(payload) {
  const m = payload.user_metadata || {}
  const n = (m.name || m.full_name || payload.name || '').trim().split(/\s+/)[0]
  return n || (payload.email ? payload.email.split('@')[0] : 'there')
}
async function sendEmail(env, to, subject, html) {
  if (!env.RESEND_API_KEY || !to) return false
  try {
    const r = await fetch('https://api.resend.com/emails', {
      method: 'POST',
      headers: { Authorization: 'Bearer ' + env.RESEND_API_KEY, 'Content-Type': 'application/json' },
      body: JSON.stringify({ from: env.EMAIL_FROM_WORKER || 'Adhyarvansh <hello@adhyarvansh.com>', to: [to], subject, html })
    })
    if (!r.ok) console.error('Resend', r.status, (await r.text()).slice(0, 200))
    return r.ok
  } catch (e) { console.error('Resend failed', e.message); return false }
}
function renderTpl(key, vars) {
  return EMAIL_TPL[key].replace(/\{\{(\w+)\}\}/g, (_, k) => escHtml(vars[k] || ''))
}

async function profileRouter(request, env, path, method) {
  let payload
  try { payload = await verifyJWT(request, env) }
  catch (e) { return err(e.message, 401) }
  const uid = payload.sub
  const userToken = getUserToken(request)
  try {
    if (path === '/profile/prefs' && method === 'GET') {
      const rows = await sbRest(userToken, 'user_prefs?select=digest_freq,statement_freq,fund_prefs&limit=1')
      if (rows && rows[0]) return ok(rows[0])
      // first visit: save the defaults shown in Settings so scheduled emails know this user's choice
      const def = { digest_freq: 'weekly', statement_freq: 'monthly', fund_prefs: null }
      try {
        const created = await sbRest(userToken, 'user_prefs?on_conflict=user_id', { method: 'POST', body: [{ user_id: uid, digest_freq: 'weekly', statement_freq: 'monthly' }], prefer: 'resolution=ignore-duplicates,return=representation' })
        if (Array.isArray(created) && created.length && payload.email) {
          // first visit: send the welcome email once
          await sendEmail(env, payload.email, 'Welcome to Adhyarvansh', renderTpl('welcome', { name: firstName(payload) }))
        }
      } catch (e) { /* table may not exist yet; still return defaults */ }
      return ok(def)
    }
    if (path === '/profile/prefs' && method === 'PUT') {
      const b = await request.json()
      const row = { user_id: uid, updated_at: new Date().toISOString() }
      if (b.digest_freq !== undefined) {
        if (!DIGEST_FREQS.includes(b.digest_freq)) return err('Invalid digest frequency', 400)
        row.digest_freq = b.digest_freq
      }
      if (b.statement_freq !== undefined) {
        if (!STATEMENT_FREQS.includes(b.statement_freq)) return err('Invalid statement frequency', 400)
        row.statement_freq = b.statement_freq
      }
      if (b.fund_prefs !== undefined) row.fund_prefs = b.fund_prefs
      await sbRest(userToken, 'user_prefs?on_conflict=user_id', {
        method: 'POST', body: [row], prefer: 'resolution=merge-duplicates,return=minimal' })
      return ok({ saved: true })
    }
    if (path === '/profile/delete' && method === 'POST') {
      const b = await request.json().catch(() => ({}))
      if (b.confirm !== 'DELETE') return err('Confirmation required', 400)
      const key = env.SUPABASE_SERVICE_KEY
      if (!key) return err('Account deletion is not configured yet. Contact the admin.', 501)
      const h = { apikey: key, Authorization: 'Bearer ' + key }
      // remove the user's rows first (child tables before parents), then the auth user
      for (const t of ['journal_exits', 'portfolio_entries', 'watchlist', 'user_prefs']) {
        const r = await fetch(SUPABASE_URL + '/rest/v1/' + t + '?user_id=eq.' + encodeURIComponent(uid), { method: 'DELETE', headers: h })
        if (!r.ok && r.status !== 404) return err('Could not delete ' + t + ' (' + r.status + ')', 502)
      }
      const r = await fetch(SUPABASE_URL + '/auth/v1/admin/users/' + encodeURIComponent(uid), { method: 'DELETE', headers: h })
      if (!r.ok) return err('Could not delete sign-in (' + r.status + ')', 502)
      const when = new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata', day: 'numeric', month: 'short', year: 'numeric', hour: 'numeric', minute: '2-digit', hour12: true }).replace(/\b(am|pm)\b/i, m => m.toUpperCase()) + ' IST'
      await sendEmail(env, payload.email, 'Your Adhyarvansh account has been deleted', renderTpl('deleted', { name: firstName(payload), when }))
      return ok({ deleted: true })
    }
    return err('Not found', 404)
  } catch (e) {
    return err(e.message || 'Profile error', e.status || 500)
  }
}


// Public brand image used in emails (white wordmark logo, 2x of 210px)
const EMAIL_LOGO_B64 = ''
const LOGO_WHITE_B64 = ''
function pngResponse(b64) {
  const bytes = Uint8Array.from(atob(b64), c => c.charCodeAt(0))
  return new Response(bytes, { headers: { 'Content-Type': 'image/png', 'Cache-Control': 'public, max-age=86400', 'Access-Control-Allow-Origin': '*' } })
}
function emailLogo() {
  const bin = atob(EMAIL_LOGO_B64)
  const bytes = Uint8Array.from(bin, c => c.charCodeAt(0))
  return new Response(bytes, { headers: { 'Content-Type': 'image/png', 'Cache-Control': 'public, max-age=86400', 'Access-Control-Allow-Origin': '*' } })
}

async function logoRoute(env, path) {
  const domain = decodeURIComponent(path.slice('/logo/'.length)).toLowerCase()
  if (!/^[a-z0-9.-]{3,80}$/.test(domain)) return new Response('Not found', { status: 404 })
  try {
    const row = await env.DB.prepare('SELECT mime, data FROM amc_logos WHERE domain = ?').bind(domain).first()
    if (!row) return new Response('Not found', { status: 404, headers: { 'Cache-Control': 'public, max-age=300' } })
    const bin = atob(row.data)
    const bytes = new Uint8Array(bin.length)
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i)
    return new Response(bytes, { headers: {
      'Content-Type': row.mime || 'image/png',
      'Cache-Control': 'public, max-age=2592000, immutable',
      'X-Content-Type-Options': 'nosniff'
    } })
  } catch (e) {
    return new Response('Not found', { status: 404 })   // table not created yet
  }
}

const ok    = (d,s=200) => new Response(JSON.stringify(d),{status:s,headers:{'Content-Type':'application/json',...CORS}})
const err   = (m,s=400) => new Response(JSON.stringify({error:m}),{status:s,headers:{'Content-Type':'application/json',...CORS}})
const toHex = b => Array.from(b).map(x=>x.toString(16).padStart(2,'0')).join('')
